INSERT OR REPLACE INTO legacy_products (id, name, category, payload_json, updated_at) VALUES ('fengshuo', '沣硕40+', '微量元素水溶肥料', '{"id":"fengshuo","name":"沣硕40+","category":"微量元素水溶肥料","intro":"微量元素水溶肥料（粉剂），含硅钙镁等40余种矿物元素，促花芽分化、防裂果、抗逆：\n\n是利用韩国独有的矿物质提纯，通过离心和活化技术提取出的多营养肥料，产品富含农作物生长所需的微量元素、中量元素、稀土元素和有益元素等多种成分，通过给农作物生长中补充均衡的养分，有助于农作物更好的生长发育，提高农产品产出和质量，本产品对农作物安全，对土壤环境友好，对农作物生长和农产品质量起到积极的帮助。","description":"含硅钙镁等40余种矿物元素，促花芽分化、防裂果、抗逆。主要成分：SiO2 38.6%、CaO 16.1%、MgO 0.5%、B 3.16%、Fe2O3 3.18%、MnO 2.44%、Zn 2.24%、Cu 0.52%","advantages":"含40余种矿物元素，营养全面；粉剂易溶，飞防灌根均可：\n\n1. 纯天然矿物质活化而成，获得有机材料认证，适合于高品质及有机农场栽培。\n2. 特有的硅钙同补，解决传统化学元素拮抗问题，混用性好，安全性高；\n3. 一次性补充中量元素、微量元素、有益元素、稀土元素达40余种，为用户节省成本；","ingredients":"SiO2 38.6%、CaO 16.1%、MgO 0.5%、K2O 3.17%、P2O5 0.13%、B 3.16%、Fe2O3 3.18%、MnO 2.44%、Zn 2.24%、Cu 0.52%、Mo 0.002%、TiO2 0.28%，另含锗、钴、锶、钒、硒、稀土等微量元素","functions":"促花芽分化、防裂果、增强抗逆性、补充硅钙及中微量元素：\n\n1.预防因缺乏营养元素带来的缺素黄化；\n2.促进花芽分化，促花保果；\n3.预防脐腐，畸形果，减少落果。\n4.预防裂果、气果，提升果实硬度和口感。\n5.提升农作物茎秆和叶片强度，提高光合作用，提升抗倒伏能力。","applicable_crops":"果树、蔬菜、大田作物均可","usage":"叶喷1200-1500倍（严重800-1000倍）；灌根150g/亩；飞防150g/5亩。粉剂","price_range":"150g/39.9元，600g/138元","mix_profile":{"ph":"7","has_copper":true,"copper_level":"medium","has_calcium":true,"has_humic_acid":false,"has_amino_acid":false,"has_microbe":false,"has_phosphorus":true,"has_silicon":true,"is_alkaline":true,"is_acidic":false},"manufacturer":"韩国丰产生物株式会社","seller":"深圳惠民皓天生态科技有限公司","origin":"韩国","registrations":{"execution_standard":"NY1428-2010","record_number":"WLSRJK2024-00744","import_contract":"XW2025-PS001","customs_declaration":"520220251025060338"},"specifications":[{"name":"15g","capacity":"15g","form":"粉剂"},{"name":"150g","capacity":"150g","form":"粉剂"},{"name":"600g","capacity":"600g","form":"粉剂"}],"custom_fields":[{"label":"产品混用禁忌","value":"傲土"}],"images":["images/products/沣硕 (1).png","images/products/沣硕.png"]}', '2026-08-22T01:14:46.869Z');
