INSERT OR REPLACE INTO legacy_product_specs (id, product_id, name, capacity, form, payload_json, sort_order) VALUES ('legacy-spec-13467c0f440f855a3e4454462624', 'fengshuo', '600g', '600g', '粉剂', '{"name":"600g","capacity":"600g","form":"粉剂"}', '2');
INSERT OR REPLACE INTO legacy_products (id, name, category, payload_json, updated_at) VALUES ('aoliang', '傲靓', '高端叶面肥', '{"id":"aoliang","name":"傲靓","category":"高端叶面肥","intro":"有机水溶肥料，LPE专利成分，作物增糖上色专用：\n\n本品系以 LPE 为核心成分的增甜着色功能营养液，其 LPE 提取自蛋黄、大豆中的天然磷脂。LPE 最初应用于医学领域，经韩国与美国联合研究发现，它对果实成熟过程中的内源激素具有正向调节作用，不仅能促进细胞膜的修复并增强其流动性，还能让叶绿体光合作用的效率大幅提升，加速糖分合成，从而提升果实甜度、促进转色。通过全球多地数百种作物开展的实验表明，傲靓 LPE 在快速提升果实甜度与色泽的同时，能有效避免口感缺失，且不会产生残留，是高品质有机农业种植的理想选择。","description":"LPE专利成分，增糖上色，转色期专用。有机钾20g/L、有机磷10g/L、有机氮8g/L、有机质400g/L","advantages":"LPE专利成分，转色增糖效果显著；可喷可浸果:\n\n1. 高含量的碳源，提升农作物的碳氮比；\n2. 独有的LPE成分，\n3. 不含任何激素成分，绿色环保安全；","ingredients":"有机钾20g/L、有机磷10g/L、有机氮8g/L、有机质400g/L、LPE（溶血磷脂酰乙醇胺）≥1%","functions":"增糖上色、促进转色、提高果实品质:\n\n1.优化果实外观与质地：修复细胞膜，让果肉质地更为紧实，果面更加光滑细腻，提升果实的商品价值。\n2.加速糖分积累与转色：提升光合作用和钾元素的转运速率，促使果实迅速积累糖分，实现快速转色，达到提前上市的目的。\n3.保障果实风味与耐储性：相比激素催熟，使用傲靓 LPE 更安全，不会对果实品质造成负面影响，同时确保果实的耐储运能力不受损害。\n4.保护树体健康：本品不会导致树体早衰，有利于果树健康及可持续生产。","applicable_crops":"葡萄、苹果、樱桃、番茄等需转色作物","usage":"转色30-40%时500-800倍喷雾，间隔12-20天。液体叶面肥，可第一次喷第二次浸果。","price_range":"200ml/199元，1000ml/899元","mix_profile":{"ph":"7.78","has_copper":false,"copper_level":"none","has_calcium":false,"has_humic_acid":false,"has_amino_acid":false,"has_microbe":false,"has_phosphorus":true,"has_silicon":false,"is_alkaline":false,"is_acidic":true},"manufacturer":"韩国艾玛易诺维株式会社","seller":"深圳惠民皓天生态科技有限公司","origin":"韩国","registrations":{"fertilizer_registration":"农肥（2022）准字18289号","execution_standard":"NY/T3831-2021","import_contract":"SR2025-1","customs_declaration":"790220251000011919"},"specifications":[{"name":"200ml","capacity":"200ml","form":"水剂","image":"images/products/aoliang_200ml.png"},{"name":"1000ml","capacity":"1L","form":"水剂","image":"images/products/aoliang_1000ml.png"}],"images":["images/products/aoliang3.png"]}', '2026-08-22T01:14:46.869Z');
