INSERT OR REPLACE INTO legacy_product_specs (id, product_id, name, capacity, form, payload_json, sort_order) VALUES ('legacy-spec-8f73c0bad39a50151af7ca302eae', 'aoliang', '1000ml', '1L', '水剂', '{"name":"1000ml","capacity":"1L","form":"水剂","image":"images/products/aoliang_1000ml.png"}', '1');
INSERT OR REPLACE INTO legacy_products (id, name, category, payload_json, updated_at) VALUES ('heiyan', '黑岩', '含氨基酸水溶肥料', '{"id":"heiyan","name":"黑岩","category":"含氨基酸水溶肥料","intro":"含氨基酸水溶肥料（水剂），富含多种氨基酸及微量元素，抗逆促长：\n\n黑岩系韩国阿米诺实验室株式会社 (AMINOLAB) 研发生产，产品以动植物双原料提取，专利酵素低温发酵技术，富含高含量的游离氨基酸，氨基酸种类达到 18 种以上，不含氯离子，分子量小，同时添加多种葡萄糖酸螯合的硼铁锰锌钼等微量元素，产品含量高，吸收好。通过补充丰富的氨基酸有利于帮助作物提升对不良环境适应能力、异常气候抵抗力、有助于解除休眠、增加叶绿素含量、促进根系发育、帮助农作物提升开花稳果、品质及产量的水平，属于清洁工艺产品，对环境及作物友好。","description":"总氨基酸≥486g/L（含谷氨酸28%、甘氨酸14%、丙氨酸12%等20种），游离氨基酸100g/L，含B、Fe、Mn、Zn、Mo、Cu等微量元素","advantages":"总氨基酸≥486g/L，20种氨基酸全覆盖；抗逆膨果双效：\n\n1. 酵素低温酶解工艺，富含18种以上氨基酸，给农作物补充全面的氨基酸营养；\n2. 动植物双源氨基酸，互补动物和植物氨基酸的含量及吸收缺陷；\n3. 486g/L的游离氨基酸，是普通氨基酸肥料的游离氨基酸含量3-4倍，含量更高，用量更少","ingredients":"总氨基酸≥486g/L、游离氨基酸100g/L（谷氨酸28.47%、甘氨酸14.16%、丙氨酸12.18%、天冬氨酸8.36%、脯氨酸6.94%等20种）、有机氮≥80g/L、B 6.8g/L、Fe 12g/L、Mn 5.5g/L、Zn 1.6g/L、Mo 0.5g/L、Cu 0.05g/L","functions":"抗逆（抗旱抗寒）、促花保果、膨果增甜、缓解药害：\n\n1.本品氨基酸种类全、吸收率高，有利于农作物生理机能活跃，促进各器官的发育作用；\n2.有助于农作物加快营养元素的运转，增加叶绿素含量，提高光合效率；\n3.补充氨基酸有利于打破作物休眠，帮助提升花芽分化、促花稳果、果实着色、提高甜度和品质的作用；\n4.合理的使用氨基酸可帮助农作物提升抗寒和逆境生长能力，帮助农作物在低温、高温情况下更快的恢复生长；\n5.如因农药使用不当造成的药害，使用氨基酸有助于缓解药害影响。","applicable_crops":"果树、蔬菜、瓜类、经济作物均可","usage":"飞防1L/15亩；灌根1L/2亩；800-1000倍喷雾。液体叶面肥","price_range":"250ml/44.9元，1000ml/149.9元","mix_profile":{"ph":"6.5","has_copper":true,"copper_level":"trace","has_calcium":false,"has_humic_acid":false,"has_amino_acid":true,"has_microbe":false,"has_phosphorus":false,"has_silicon":false,"is_alkaline":false,"is_acidic":true},"manufacturer":"韩国阿米诺实验室株式会社","seller":"深圳惠民皓天生态科技有限公司","origin":"韩国","registrations":{"customs_declaration":"425820261000062043","import_contract":"HMCG06-AL001","fertilizer_registration":"农肥（2025）准字20124号","execution_standard":"NY1429-2010"},"specifications":[{"name":"20ml","capacity":"20ml","form":"粉剂/袋装","image":"images/products/heiyan_20ml.png"},{"name":"250ml","capacity":"250ml","form":"水剂","image":"images/products/heiyan_250ml.png"},{"name":"1000ml","capacity":"1000ml","form":"水剂","image":"images/products/heiyan_1000ml.png"}],"images":["images/products/heiyan_20ml.png","images/products/heiyan_250ml.png","images/products/heiyan_1000ml.png"],"pesticide_compat":[{"pesticide":"铜制剂","status":"forbidden","reason":"氨基酸与铜离子发生络合反应，降低双方药效"},{"pesticide":"波尔多液","status":"forbidden","reason":"含铜，与氨基酸络合"},{"pesticide":"石硫合剂","status":"caution","reason":"强碱性，建议间隔使用"}]}', '2026-08-22T01:14:46.869Z');
