INSERT OR REPLACE INTO legacy_product_compatibility (id, product_id, pesticide_name, status, reason) VALUES ('legacy-compat-72e707d6a89021e1353588567355', 'heiyan', '石硫合剂', 'caution', '强碱性，建议间隔使用');
INSERT OR REPLACE INTO legacy_products (id, name, category, payload_json, updated_at) VALUES ('aomai', '傲脉', '有机水溶肥料', '{"id":"aomai","name":"傲脉","category":"有机水溶肥料","intro":"有机水溶肥料（水剂），零激素营养型生根肥，调土生根、促长提质:\n\n韩国进口有机水溶肥，核心成分黄腐酸≥280g/L、蛋白质≥220g/L、有机质≥320g/L，另含18种氨基酸及钙镁硼锌。根际肥，冲施滴灌，不做叶喷。零激素营养型生根养根，短期生毛细根、中期根系健壮、长期养根护根三重效果。改善土壤板结、酸化、盐渍化，促进团粒结构形成，抗重茬。激活内源酶提高免疫力，抵御冻害，减少落果畸形和土传病害。配合微生物菌剂（傲生）使用效果最佳，可降氮磷钾用量20-30%。五大核心产品之一，根际肥销量TOP1。注意：蛋白质含氮，转色期禁用。","description":"零激素营养型生根肥，黄腐酸280g/L+腐殖酸30g/L+鱼蛋白220g/L+氨基酸80g/L，含Ca、Mg、B、Zn","advantages":"零激素，生根不依赖刺激；黄腐酸+鱼蛋白+氨基酸三重有机营养","ingredients":"有机质320g/L、黄腐酸280g/L、蛋白质220g/L、腐殖酸30g/L、游离氨基酸≥80g/L、有机氮≥35g/L、磷≥5g/L、钾≥50g/L、Ca≥5g/L、Mg≥10g/L、B+Zn 20g/L","functions":"生根养根、改良土壤、促进根系发育、无激素\n1.补充土壤有机质：补充土壤有机质可改善土壤物理性质，提升土壤保水保肥能力，促进微生物活动，缓解土壤酸化、板结和盐渍化。\n2.促生根壮苗：提高土壤有益微生物活跃度，抗重茬连作障碍，促进主根和毛细根生长，提升氮磷钾吸收效率。\n3.促长提升品质：富含 18 种以上氨基酸、蛋白质、钙镁和微量元素，让作物吸收更全面均衡的营养物质，提升水果蔬菜的品质，提高农产品甜度、品质和口感。\n4.提高作物活力：提升作物内源生物酶活性，调节作物生理机能，有助于提升作物抗逆能力，减少土传问题，促进作物健康生长。","applicable_crops":"果树、蔬菜、瓜类、大田作物均可","usage":"定根300-500倍或2-3kg/亩；提苗/膨果250-300倍或4-5kg/亩。液体根际肥，不做叶喷","price_range":"4kg/88元，20kg/360元","mix_profile":{"ph":"6.24","has_copper":false,"copper_level":"none","has_calcium":true,"has_humic_acid":true,"has_amino_acid":true,"has_microbe":false,"has_phosphorus":true,"has_silicon":false,"is_alkaline":false,"is_acidic":true},"manufacturer":"韩国艾玛易诺维株式会社","seller":"深圳惠民皓天生态科技有限公司","origin":"韩国","specifications":[{"name":"4Kg","capacity":"4Kg","form":"水剂（桶装）"},{"name":"20Kg","capacity":"20Kg","form":"水剂（桶装）"}],"images":["images/products/aomai_4kg.png","images/products/aomai_20kg.png"]}', '2026-08-22T01:14:46.869Z');
