INSERT OR REPLACE INTO legacy_products (id, name, category, payload_json, updated_at) VALUES ('aosheng', '傲生', '微生物菌剂', '{"id":"aosheng","name":"傲生","category":"微生物菌剂","intro":"微生物菌剂（粉剂），8大复合菌群，调土防病、解磷解钾\n\n傲生不属于单一菌种的微生物菌剂，更强调真菌与细菌多菌种的共生关系。其核心技术与部分菌株由日本提供，并在国内进行二次培育，其中包含了枯草芽孢杆菌、地衣芽孢杆菌、巨大芽孢杆菌、侧孢短芽孢杆菌、哈茨木霉菌、拟青霉等。通过给土壤施用多种经科学筛选和配比的有益微生物，具有间接改良土壤、恢复地力、维持土壤微生物区系平衡、降解有毒有害物质的作用，以及增加植物根系养分供应或促进植物生长的作用。有利于改善土壤连作障碍和长期过量使用农药化肥导致的盐碱化、板结及重茬问题，提升土壤有机质和化肥转化利用率，促进作物根系发达，从而改善农产品品质及农业生态环境。","description":"8大复合菌群：枯草芽孢杆菌80亿、巨大芽孢杆菌10.8亿、侧孢短芽孢杆菌8.5亿、哈茨木霉菌5.2亿、娄彻氏链霉菌2亿、光合细菌0.2亿、地衣芽孢杆菌0.2亿、拜赖青霉菌0.2亿","advantages":"8大复合菌群协同；枯草芽孢杆菌80亿/g，菌种丰富]\n\n1. 活性高，优秀的载体保持菌在储藏以及使用中的高活性；\n2. 真菌+细菌共生，核心技术及原料来源于日本，更权威和专业；\n3. 8大菌种复合，解决土壤及根部真菌和细菌多种菌失衡问题；","ingredients":"枯草芽孢杆菌80亿/g、巨大芽孢杆菌10.8亿/g、侧孢短芽孢杆菌8.5亿/g、哈茨木霉菌5.2亿/g、娄彻氏链霉菌2亿/g、光合细菌0.2亿/g、地衣芽孢杆菌0.2亿/g、拜赖青霉菌0.2亿/g、细真菌类50亿/g","functions":"调土、防土传病害、解磷解钾、固氮、促根\n\n调土生根：改善土壤环境，促进根系生长，增强作物吸水吸肥能力。\n解磷解钾：帮助转化土壤中固定的磷、钾等养分，提高养分利用率。\n提升肥效：促进营养元素吸收，提高肥料利用效率，减少养分浪费。\n土壤修复：通过微生物作用改善土壤板结、盐渍化和连作障碍问题。","applicable_crops":"果树、蔬菜、大田作物均可","usage":"500g/亩或兑水1000倍，间隔20-30天。液体根际肥，不做叶喷","price_range":"500g/59.9元","mix_profile":{"ph":"7","has_copper":false,"copper_level":"none","has_calcium":false,"has_humic_acid":false,"has_amino_acid":false,"has_microbe":true,"has_phosphorus":false,"has_silicon":false,"is_alkaline":false,"is_acidic":false},"manufacturer":"湖北中向生物工程有限公司","seller":"深圳惠民皓天生态科技有限公司","origin":"中国","specifications":[{"name":"30g","capacity":"30g","form":"粉剂"},{"name":"500g","capacity":"500g","form":"粉剂"}],"images":["images/products/aosheng_30g.png","images/products/aosheng_500g.png"]}', '2026-08-22T01:14:46.869Z');
