INSERT OR REPLACE INTO legacy_products (id, name, category, payload_json, updated_at) VALUES ('aolei', '傲蕾', '有机水溶肥料', '{"id":"aolei","name":"傲蕾","category":"有机水溶肥料","intro":"天然生物刺激素（水剂），打破休眠、控叶促花、调节平衡、稳果转绿：\n\n傲蕾系通过高等植物、种子、藻类提纯的天然生物刺激素。含有大量的微量元素营养、氨基酸、有机酸、维生素和天然植物源调剂，是为农作物开花结果研发的专用产品，傲蕾对农作物亲和力强，吸收效率高、绿色安全，特别适合农作物春冬季节促花期使用能帮助农作物抗低温打破休眠，提升开花的整齐度和稳果效率，是农业种植不可缺的功能性有机水溶肥料。","description":"B 3.6g/L、Fe 4.3g/L、Mn 3g/L、Zn 2.8g/L、Cu 0.5g/L、Mo 0.02g/L，含氨基酸30g/L、有机质160g/L、维生素及抗氧化剂1000ppm、天然植物刺激素1000ppm","advantages":"天然生物刺激素，非激素调节；打破休眠、控叶促花一药多效：\n\n1.采用高达30%的天然植物与藻类提取物作为核心刺激素，内含多种天然内源调节物质与有机酸，完全不依赖化学人工激素即可实现对作物的安全生理激活；\n2.\t罕见地复配了高浓度叶酸与维生素抗氧化剂，这两类物质能强效保护植物细胞膜免受低温等异常气候的损伤；\n3.\t精准定位于生殖生长的养分结构，采用极低氮低磷配合高活性的铁、硼、锌，通过微量元素的强效协同直接驱动花器官的发育。","ingredients":"B 3.6g/L、Fe 4.3g/L、Mn 3g/L、Zn 2.8g/L、Cu 0.5g/L、Mo 0.02g/L、氨基酸30g/L、有机质160g/L、维生素及抗氧化剂1000ppm、叶酸1000ppm、天然植物刺激素1000ppm、天然增效剂30%","functions":"促进花芽分化、提高坐果率、保花保果、补充微量元素","applicable_crops":"果树、蔬菜、瓜类、经济作物均可","usage":"冒芽800-1000倍间隔10-15天；见花苞和谢花后1000倍。液体叶面肥","price_range":"200ml/69.9元，1000ml/318元","mix_profile":{"ph":"9","has_copper":true,"copper_level":"low","has_calcium":false,"has_humic_acid":false,"has_amino_acid":true,"has_microbe":false,"has_phosphorus":false,"has_silicon":false,"is_alkaline":false,"is_acidic":true},"manufacturer":"韩国艾玛易诺维株式会社","seller":"深圳惠民皓天生态科技有限公司","origin":"中国","specifications":[{"name":"200ml","capacity":"200ml","form":"水剂","image":"images/products/aolei_200ml.png"},{"name":"1000ml","capacity":"1000ml","form":"水剂","image":"images/products/aolei_1000ml.png"}],"images":["images/products/aolei_200ml.png","images/products/aolei_1000ml.png"]}', '2026-08-22T01:14:46.869Z');
