INSERT OR REPLACE INTO legacy_products (id, name, category, payload_json, updated_at) VALUES ('shikeshou', '施可收', '大量元素水溶肥料', '{"id":"shikeshou","name":"施可收","category":"大量元素水溶肥料","intro":"有机无机复合水溶肥（水剂），三个配方满足提苗、平衡、膨果需求","description":"有机质≥100g/L，含复合菌、B 3g/L、Zn 1g/L、Mn 1g/L、Cu 1g/L。三个配方：提苗型(250-150-100)、平衡型(170-170-170)、膨果型(80-120-300)，pH 5.0-6.5","advantages":"三配方覆盖全生育期；有机+无机+微生物三效合一\n有机无机：科学的大、中、微量元素及有机物配比，改善土壤物理性质，提升土壤的保水保肥能力。\n特殊菌群：独特的复合微生物菌群，有效抑制有害生物活性，对土壤恶化、连作障碍、抗逆能力提升有积极作用。\n节省成本：无需另外搭配氮磷钾成分使用，产品高效，降低用肥成本。\n使用便捷：有机无机同补，为作物不同阶段提供应激配方，减少人工作业成本。","ingredients":"有机质≥100g/L、复合菌（不强调）、B(非螯合)3g/L、Zn 1g/L、Mn 1g/L、Cu 1g/L。三个配方：提苗型N-P2O5-K2O=250-150-100、平衡型170-170-170、膨果型80-120-300。pH 5.0-6.5","functions":"提苗促长（提苗型）、营养均衡（平衡型）、膨果转色（膨果型），改良土壤、提高肥料利用率\n\n1. 有机无机结合，高浓度大量元素和有机质，利用有机胶体缓冲无机盐渗透压刺激，实现高效补肥且不伤根；\n2. 突破高盐度限制，成功融入复合微生物菌群，实现营养快速补充和根际微生态改良同步进行；\n3. 针对快速生长期需求，配比微量元素，预防提苗阶段的隐性缺素问题。","applicable_crops":"果树、蔬菜、瓜类等经济作物","usage":"3-5kg/亩或300-500倍。液体根际肥，冲施滴灌，不做叶喷","price_range":"提苗型4kg/94元、20kg/460元；平衡型4kg/99元、20kg/480元；膨果型4kg/99元、20kg/480元","mix_profile":{"ph":"5.66","has_copper":true,"copper_level":"medium","has_calcium":false,"has_humic_acid":false,"has_amino_acid":false,"has_microbe":true,"has_phosphorus":true,"has_silicon":false,"is_alkaline":false,"is_acidic":true},"manufacturer":"深圳惠民皓天生态科技有限公司","seller":"深圳惠民皓天生态科技有限公司","origin":"中国","specifications":[{"name":"4Kg","capacity":"4Kg","form":"水剂"}],"images":["images/products/shikeshou20kg平衡.jpg","images/products/shikeshou20kg提苗.jpg","images/products/shikeshou20kg膨果.jpg","images/products/shikeshou4kg平衡.jpg","images/products/shikeshou4kg提苗.jpg","images/products/shikeshou4kg膨果.jpg"]}', '2026-08-22T01:14:46.869Z');
