INSERT OR REPLACE INTO legacy_products (id, name, category, payload_json, updated_at) VALUES ('aoye', '傲叶', '含氨基酸水溶肥料', '{"id":"aoye","name":"傲叶","category":"含氨基酸水溶肥料","intro":"有机水溶肥料（水剂），鱼蛋白为核心，沃土养根、绿叶健长、改善品质\n\n傲叶采用深海鱼为原料，将鱼肉、骨、内脏进行分离后，对杂菌、盐、氯等进行无害化处理，保持原料新鲜度的情况下进行 TDN 技术转换，生物酶分解提取。本品的有机质、腐殖质、蛋白质及氨基酸含量高，分子量小，易被作物吸收，适用于多种绿色高品质种植。","description":"鱼蛋白380g/L+氨基酸300g/L（游离100g/L），含有机质300g/L、有机氮≥80g/L、磷≥60g/L、钾≥60g/L、Ca 5g/L、Mg 5g/L、B 5g/L、Zn 5g/L","advantages":"鱼蛋白380g/L含量高；沃土养根兼顾叶面营养\n\n1. 采用深海鱼为原料生物酶解工艺，保留丰富的游离氨基酸和多肽，分子小，直接吸收利用率极高；\n2. 高浓度有机质、氨基酸及中微量元素，碳氮比更平衡，营养更全面；\n3. 快速传导至生长点，适合于叶面喷雾以及根部滴管。","ingredients":"鱼蛋白380g/L、总氨基酸300g/L（游离氨基酸100g/L）、有机质300g/L、有机氮≥80g/L、P2O5≥60g/L、K2O≥60g/L、Ca 5g/L、Mg 5g/L、B 5g/L、Zn 5g/L","functions":"促进叶片生长、增强光合作用、使叶片浓绿肥厚\n\n含丰富的有机碳、高蛋白、多肽氨基酸、钙镁和微量元素，提高土壤有机质含量，促进土壤微生物繁殖，改善土壤环境，促进根系生长。\n提高作物的光合作用和环境适应能力，促进叶片转绿肥厚，改善苗势，提升低温和高温下的适应能力。\n有助于开花挂果，提高作物的品质、品相、口感和糖分。\n本品天然有机，安全性高，适用范围广，可叶面喷施、滴灌、灌根、淋根等多种使用方法。","applicable_crops":"果树、蔬菜、瓜类、大田作物均可","usage":"叶面1L/10-15亩或800-1200倍；根用1L/亩或500-800倍。液体叶面肥","price_range":"200ml/19.9元，1000ml/69.8元","mix_profile":{"ph":"6.5","has_copper":false,"copper_level":"none","has_calcium":true,"has_humic_acid":false,"has_amino_acid":true,"has_microbe":false,"has_phosphorus":true,"has_silicon":false,"is_alkaline":false,"is_acidic":true},"manufacturer":"韩国艾玛易诺维株式会社","seller":"深圳惠民皓天生态科技有限公司","origin":"韩国","specifications":[{"name":"200ml","capacity":"200ml","form":"水剂","image":"images/products/aoye_200ml.png"},{"name":"1000ml","capacity":"1000ml","form":"水剂","image":"images/products/aoye_1000ml.png"}],"images":["images/products/aoye_200ml.png","images/products/aoye_1000ml.png"]}', '2026-08-22T01:14:46.869Z');
